powerCycle(): void {
  this.metrics.powerCycles += 1;
  this.armed = false;
  this.on = true;
  // A plug-pull drops anything in flight: replies queued before the cycle
  // must not surface after reconnect (step 15 keys on the next answer).
  this.queue = [];
  this.waiters.forEach((waiter) => { waiter.settle(null); });
  this.waiters = [];
  // Derived paint state belongs to the old session; a post-cycle assertion
  // must not read a pre-cycle value (and a stale lastPaintAt can turn the
  // first post-reconnect paint into a spurious stutter).
  this.lastPaintLanded = false;
  this.lastPaintReason = "none";
  this.landedDelayMs = null;
  this.lastPaintAt = 0;

